mapper.update:
update edu_enrollment
offering_id = #{offeringId}, student_id = #{studentId}, usual_score = #{usualScore}, exam_score = #{examScore}, total_score = #{totalScore}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where enrollment_id = #{enrollmentId}

